CREATE OR REPLACE FUNCTION public.finish_roleplay_session(p_session_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.roleplay_sessions; points integer; BEGIN SELECT * INTO s FROM public.roleplay_sessions WHERE id=p_session_id FOR UPDATE; IF s.id IS NULL OR NOT s.ended OR s.stars IS NULL THEN RAISE EXCEPTION 'Scene is not complete'; END IF; IF s.awarded THEN RETURN 0; END IF; points:=s.stars*10; INSERT INTO public.xp_events(user_id,points,reason) VALUES(s.user_id,points,'roleplay_'||s.scene_id); UPDATE public.impact_counters SET bricks=bricks+points WHERE id=1; UPDATE public.roleplay_sessions SET awarded=true WHERE id=s.id; RETURN points; END; $$; REVOKE ALL ON FUNCTION public.finish_roleplay_session(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_roleplay_session(uuid) TO service_role;